from __future__ import annotations
from .canonical import seal
def qualify_release(registry:dict,placement:dict,rollout:dict,reconciliation:dict,chaos:dict,observability:dict,evidence:dict)->dict:
 internal=all([registry["immutable"],placement["deterministic"],not placement["overcommit"],rollout["fleet_reference_ready"],reconciliation["reconciled"],chaos["uncontained_count"]==0,observability["unknown_cells"]==0])
 return seal({"phase":"SAED_V4_40","status":"ACCEPTED_REFERENCE_EXTERNAL_GATES_OPEN" if internal else "REJECTED","internal_reference_gates_passed":internal,"cell_count":len(registry["cells"]),"replica_count":placement["assignment_count"],"context_fleet_reference_ready":internal,"actual_scale_soak_passed":False,"actual_failover_passed":False,"live_order_submission_allowed":False,"capital_activation_allowed":False,"production_authorized":False,"research_only":True,"claim_ceiling":"deterministic synthetic context-fleet control-plane and scaleout reference only"},"v440_release","release_id","release_hash")
